class Solution {
public:
    int minimizeTheDifference(vector<vector<int>>& mat, int target) {
        bitset<5000> bs;
        bs[0] = 1;
        for (const auto& row : mat) {
            bitset<5000> nextBs;
            for (int x : row) {
                nextBs |= (bs << x);
            }
            bs = nextBs;
        }
        int ans = INT_MAX;
        for (int i = 0; i < 5000; i++) {
            if (bs[i]) {
                ans = min(ans, abs(i - target));
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minimizeTheDifference(int[][] mat, int target) {
        Set<Integer> possible = new HashSet<>();
        possible.add(0);
        for (int[] row : mat) {
            Set<Integer> next = new HashSet<>();
            int minExceeding = Integer.MAX_VALUE;
            for (int s : possible) {
                for (int x : row) {
                    int val = s + x;
                    if (val >= target) {
                        minExceeding = Math.min(minExceeding, val);
                    } else {
                        next.add(val);
                    }
                }
            }
            if (minExceeding != Integer.MAX_VALUE) next.add(minExceeding);
            possible = next;
        }
        int ans = Integer.MAX_VALUE;
        for (int s : possible) {
            ans = Math.min(ans, Math.abs(s - target));
        }
        return ans;
    }
}

var minimizeTheDifference = function(mat, target) {
  let possible = new Set([0]);
  for (const row of mat) {
    const next = new Set();
    let minExceeding = Infinity;
    for (const s of possible) {
      for (const x of row) {
        const val = s + x;
        if (val >= target) {
          if (val < minExceeding) minExceeding = val;
        } else {
          next.add(val);
        }
      }
    }
    if (minExceeding !== Infinity) next.add(minExceeding);
    possible = next;
  }
  let ans = Infinity;
  for (const s of possible) {
    ans = Math.min(ans, Math.abs(s - target));
  }
  return ans;
